/**
 * Broker OS database schema (Drizzle ORM, Postgres).
 *
 * Conventions every table follows:
 *  - id: uuid primary key, generated by the database
 *  - workspace_id: every row belongs to exactly one workspace (the sharing unit)
 *  - created_at / updated_at: timestamps with time zone
 *  - money: numeric(14,2); rates: numeric(6,3); calendar dates: date (YYYY-MM-DD strings)
 *
 * v0.2 added checklist_items, tasks, activities and renewal_outcomes; v0.4
 * added claims; v1 added tower_layers, contract_requirements, certificates,
 * policy_participants and policy_sublimits. Later versions add submissions,
 * quotes and quote_options via new migrations.
 * Keep the helper column factories below so those tables stay consistent.
 */
import { relations, sql } from "drizzle-orm";
import {
  boolean,
  date,
  index,
  integer,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
  uniqueIndex,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";
import { LAYER_TYPES, LINE_GROUPS, REQUIREMENT_COVERAGES } from "@/lib/domain/program";
import {
  ACCOUNT_STATUSES,
  ACTIVITY_KINDS,
  CHECKLIST_SOURCES,
  CLAIM_STATUSES,
  PARTICIPANT_ROLES,
  ENDORSEMENTS,
  LOST_REASONS,
  OUTCOME_TYPES,
  EXPOSURE_BASES,
  LINES_OF_BUSINESS,
  RENEWAL_STATUSES,
} from "@/lib/constants";

export const accountStatusEnum = pgEnum("account_status", ACCOUNT_STATUSES);
export const lineOfBusinessEnum = pgEnum("line_of_business", LINES_OF_BUSINESS);
export const exposureBasisEnum = pgEnum("exposure_basis", EXPOSURE_BASES);
export const renewalStatusEnum = pgEnum("renewal_status", RENEWAL_STATUSES);
export const endorsementEnum = pgEnum("endorsement", ENDORSEMENTS);
export const checklistSourceEnum = pgEnum("checklist_source", CHECKLIST_SOURCES);
export const activityKindEnum = pgEnum("activity_kind", ACTIVITY_KINDS);
export const outcomeTypeEnum = pgEnum("outcome_type", OUTCOME_TYPES);
export const lostReasonEnum = pgEnum("lost_reason", LOST_REASONS);
export const claimStatusEnum = pgEnum("claim_status", CLAIM_STATUSES);
export const lineGroupEnum = pgEnum("line_group", LINE_GROUPS);
export const layerTypeEnum = pgEnum("layer_type", LAYER_TYPES);
export const requirementCoverageEnum = pgEnum("requirement_coverage", REQUIREMENT_COVERAGES);
export const participantRoleEnum = pgEnum("participant_role", PARTICIPANT_ROLES);

/** Column helpers so every table shares the same audit columns and types. */
const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};
const money = (name: string) => numeric(name, { precision: 14, scale: 2, mode: "number" });
const rate = (name: string) => numeric(name, { precision: 6, scale: 3, mode: "number" });

export const workspaces = pgTable("workspaces", {
  id: uuid("id").primaryKey().defaultRandom(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  asOfDate: date("as_of_date", { mode: "string" }).notNull(),
  ...timestamps,
});

export const accounts = pgTable(
  "accounts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    industry: text("industry").notNull(),
    annualRevenue: money("annual_revenue"),
    employeeCount: integer("employee_count"),
    province: text("province").notNull(),
    producer: text("producer"),
    accountManager: text("account_manager"),
    status: accountStatusEnum("status").notNull().default("prospect"),
    notes: text("notes"),
    ...timestamps,
  },
  (t) => [index("accounts_workspace_idx").on(t.workspaceId), index("accounts_workspace_name_idx").on(t.workspaceId, t.name)],
);

export const contacts = pgTable(
  "contacts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    role: text("role"),
    email: text("email"),
    phone: text("phone"),
    ...timestamps,
  },
  (t) => [index("contacts_account_idx").on(t.accountId), index("contacts_workspace_idx").on(t.workspaceId)],
);

export const policies = pgTable(
  "policies",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    carrier: text("carrier").notNull(),
    lineOfBusiness: lineOfBusinessEnum("line_of_business").notNull(),
    policyNumber: text("policy_number"),
    effectiveDate: date("effective_date", { mode: "string" }).notNull(),
    expiryDate: date("expiry_date", { mode: "string" }).notNull(),
    occurrenceLimit: money("occurrence_limit"),
    aggregateLimit: money("aggregate_limit"),
    deductible: money("deductible"),
    annualPremium: money("annual_premium").notNull(),
    commissionRate: rate("commission_rate").notNull(),
    exposureBasis: exposureBasisEnum("exposure_basis").notNull(),
    exposureAmount: money("exposure_amount"),
    endorsements: endorsementEnum("endorsements")
      .array()
      .notNull()
      .default(sql`'{}'::endorsement[]`),
    renewalStatus: renewalStatusEnum("renewal_status").notNull().default("not_started"),
    previousPolicyId: uuid("previous_policy_id").references((): AnyPgColumn => policies.id, { onDelete: "set null" }),
    notes: text("notes"),
    /**
     * The renewal stage last written to the activity log (v0.2). Stage itself is
     * always derived from the as-of date; this only lets us detect changes.
     */
    lastLoggedStage: text("last_logged_stage"),
    /** v1, Property policies: insurable value and coinsurance clause for the adequacy panel. */
    insurableValue: money("insurable_value"),
    coinsurancePercent: rate("coinsurance_percent"),
    ...timestamps,
  },
  (t) => [
    index("policies_account_idx").on(t.accountId),
    index("policies_workspace_idx").on(t.workspaceId),
    index("policies_workspace_expiry_idx").on(t.workspaceId, t.expiryDate),
  ],
);

/* ---------- v0.2 Renewals ---------- */

export const checklistItems = pgTable(
  "checklist_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    policyId: uuid("policy_id")
      .notNull()
      .references(() => policies.id, { onDelete: "cascade" }),
    label: text("label").notNull(),
    required: boolean("required").notNull().default(true),
    done: boolean("done").notNull().default(false),
    source: checklistSourceEnum("source").notNull(),
    sortOrder: integer("sort_order").notNull().default(0),
    ...timestamps,
  },
  (t) => [uniqueIndex("checklist_items_policy_label_uq").on(t.policyId, t.label), index("checklist_items_workspace_idx").on(t.workspaceId)],
);

export const tasks = pgTable(
  "tasks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    policyId: uuid("policy_id").references(() => policies.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    dueDate: date("due_date", { mode: "string" }).notNull(),
    owner: text("owner"),
    done: boolean("done").notNull().default(false),
    ...timestamps,
  },
  (t) => [
    index("tasks_workspace_due_idx").on(t.workspaceId, t.dueDate),
    index("tasks_account_idx").on(t.accountId),
    index("tasks_policy_idx").on(t.policyId),
  ],
);

export const activities = pgTable(
  "activities",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    /** Kept when the policy is deleted so the history survives. */
    policyId: uuid("policy_id").references(() => policies.id, { onDelete: "set null" }),
    kind: activityKindEnum("kind").notNull(),
    body: text("body").notNull(),
    /** The workspace as-of date when the entry was written. */
    asOfDate: date("as_of_date", { mode: "string" }).notNull(),
    ...timestamps,
  },
  (t) => [index("activities_account_idx").on(t.accountId, t.createdAt), index("activities_workspace_idx").on(t.workspaceId)],
);

/** One row per policy that has an outcome. Deleting the row (Undo) reopens the policy. */
export const renewalOutcomes = pgTable(
  "renewal_outcomes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    policyId: uuid("policy_id")
      .notNull()
      .references(() => policies.id, { onDelete: "cascade" }),
    outcome: outcomeTypeEnum("outcome").notNull(),
    lostReason: lostReasonEnum("lost_reason"),
    /** Non-renewal reason, or extra detail for a lost outcome. */
    reason: text("reason"),
    competingPremium: money("competing_premium"),
    successorPolicyId: uuid("successor_policy_id").references((): AnyPgColumn => policies.id, { onDelete: "set null" }),
    /** Renewal status before the outcome, restored by Undo. */
    priorStatus: renewalStatusEnum("prior_status").notNull(),
    recordedAsOf: date("recorded_as_of", { mode: "string" }).notNull(),
    ...timestamps,
  },
  (t) => [uniqueIndex("renewal_outcomes_policy_uq").on(t.policyId), index("renewal_outcomes_workspace_idx").on(t.workspaceId)],
);

/* ---------- v0.4 Loss runs ---------- */

/**
 * Claims from loss runs. Incurred (paid + reserved) and the policy year are
 * derived in src/lib/domain/lossRuns.ts and never stored. Claim numbers are not
 * unique: duplicates are allowed and flagged.
 */
export const claims = pgTable(
  "claims",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    /** Optional link to the account's policy in the same line; kept when the policy is deleted. */
    policyId: uuid("policy_id").references(() => policies.id, { onDelete: "set null" }),
    lineOfBusiness: lineOfBusinessEnum("line_of_business").notNull(),
    claimNumber: text("claim_number").notNull(),
    dateOfLoss: date("date_of_loss", { mode: "string" }).notNull(),
    dateReported: date("date_reported", { mode: "string" }).notNull(),
    description: text("description"),
    paid: money("paid").notNull(),
    reserved: money("reserved").notNull(),
    status: claimStatusEnum("status").notNull(),
    ...timestamps,
  },
  (t) => [
    index("claims_account_line_idx").on(t.accountId, t.lineOfBusiness),
    index("claims_account_number_idx").on(t.accountId, t.claimNumber),
    index("claims_policy_idx").on(t.policyId),
    index("claims_workspace_idx").on(t.workspaceId),
  ],
);

/* ---------- v1 Program ---------- */

export const towerLayers = pgTable(
  "tower_layers",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    lineGroup: lineGroupEnum("line_group").notNull(),
    layerType: layerTypeEnum("layer_type").notNull(),
    attachment: money("attachment").notNull(),
    limit: money("limit").notNull(),
    premium: money("premium").notNull(),
    carrier: text("carrier").notNull(),
    policyId: uuid("policy_id").references(() => policies.id, { onDelete: "set null" }),
    ...timestamps,
  },
  (t) => [index("tower_layers_account_group_idx").on(t.accountId, t.lineGroup), index("tower_layers_workspace_idx").on(t.workspaceId)],
);

export const contractRequirements = pgTable(
  "contract_requirements",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    contractName: text("contract_name").notNull(),
    counterparty: text("counterparty").notNull(),
    coverage: requirementCoverageEnum("coverage").notNull(),
    requiredOccurrence: money("required_occurrence"),
    requiredAggregate: money("required_aggregate"),
    requiredEndorsements: endorsementEnum("required_endorsements")
      .array()
      .notNull()
      .default(sql`'{}'::endorsement[]`),
    notes: text("notes"),
    ...timestamps,
  },
  (t) => [index("contract_requirements_account_idx").on(t.accountId), index("contract_requirements_workspace_idx").on(t.workspaceId)],
);

/** Certificate status (requested / issued / expired / reissue needed) is derived in src/lib/domain/program.ts, never stored. */
export const certificates = pgTable(
  "certificates",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    holder: text("holder").notNull(),
    operationsDescription: text("operations_description"),
    coverages: lineOfBusinessEnum("coverages")
      .array()
      .notNull()
      .default(sql`'{}'::line_of_business[]`),
    requiredBy: date("required_by", { mode: "string" }),
    issuedOn: date("issued_on", { mode: "string" }),
    notes: text("notes"),
    ...timestamps,
  },
  (t) => [index("certificates_account_idx").on(t.accountId), index("certificates_workspace_idx").on(t.workspaceId)],
);

/** Co-insurers on a larger placement. The policy's own carrier is the lead; rows here are the full signed-line schedule. */
export const policyParticipants = pgTable(
  "policy_participants",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    policyId: uuid("policy_id")
      .notNull()
      .references(() => policies.id, { onDelete: "cascade" }),
    carrier: text("carrier").notNull(),
    role: participantRoleEnum("role").notNull().default("follow"),
    /** Percent of the placement, e.g. 50.000. */
    signedLine: rate("signed_line").notNull(),
    premium: money("premium"),
    notes: text("notes"),
    ...timestamps,
  },
  (t) => [index("policy_participants_policy_idx").on(t.policyId), index("policy_participants_workspace_idx").on(t.workspaceId)],
);

/** Sub-limits and their own deductibles (earthquake, flood, stock…). The policy's limit and deductible stay the defaults. */
export const policySublimits = pgTable(
  "policy_sublimits",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    policyId: uuid("policy_id")
      .notNull()
      .references(() => policies.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    limit: money("limit"),
    deductible: money("deductible"),
    notes: text("notes"),
    ...timestamps,
  },
  (t) => [index("policy_sublimits_policy_idx").on(t.policyId), index("policy_sublimits_workspace_idx").on(t.workspaceId)],
);

export const workspacesRelations = relations(workspaces, ({ many }) => ({
  accounts: many(accounts),
  contacts: many(contacts),
  policies: many(policies),
}));

export const accountsRelations = relations(accounts, ({ one, many }) => ({
  workspace: one(workspaces, { fields: [accounts.workspaceId], references: [workspaces.id] }),
  contacts: many(contacts),
  policies: many(policies),
}));

export const contactsRelations = relations(contacts, ({ one }) => ({
  account: one(accounts, { fields: [contacts.accountId], references: [accounts.id] }),
}));

export const policiesRelations = relations(policies, ({ one }) => ({
  account: one(accounts, { fields: [policies.accountId], references: [accounts.id] }),
  previousPolicy: one(policies, {
    fields: [policies.previousPolicyId],
    references: [policies.id],
    relationName: "previousPolicy",
  }),
}));

export type Workspace = typeof workspaces.$inferSelect;
export type Account = typeof accounts.$inferSelect;
export type NewAccount = typeof accounts.$inferInsert;
export type Contact = typeof contacts.$inferSelect;
export type NewContact = typeof contacts.$inferInsert;
export type Policy = typeof policies.$inferSelect;
export type NewPolicy = typeof policies.$inferInsert;
export type ChecklistItem = typeof checklistItems.$inferSelect;
export type Task = typeof tasks.$inferSelect;
export type Activity = typeof activities.$inferSelect;
export type RenewalOutcome = typeof renewalOutcomes.$inferSelect;
export type Claim = typeof claims.$inferSelect;
export type TowerLayer = typeof towerLayers.$inferSelect;
export type ContractRequirement = typeof contractRequirements.$inferSelect;
export type Certificate = typeof certificates.$inferSelect;
export type PolicyParticipant = typeof policyParticipants.$inferSelect;
export type PolicySublimit = typeof policySublimits.$inferSelect;
